#include <stdio.h>
int binsearch(int a[], int n, int k)
{
int low = 0, high = n - 1, mid;
while (low <= high) {
mid = (low + high) / 2;
if (a[mid] == k) return mid;
else if (a[mid] < k) low = mid + 1;
else high = mid - 1;
}
return -1;
}
int main(void)
{
int a[6] = {1, 3, 5, 7, 9, 11}, k;
scanf("%d", &k);
printf("%d\n", binsearch(a, 6, k));
return 0;
}

